-- SoulVector Russian-focused stylometry v2.
-- IMPORTANT: the old 48D vectors are invalid under the new schema. Clear them;
-- profiles must be re-analysed or regenerated by scripts/seed-demo.ts.

DROP INDEX IF EXISTS public.sv_profiles_author_style_hnsw_idx;

ALTER TABLE public.sv_profiles
  ALTER COLUMN author_style_embedding
  TYPE extensions.vector(512)
  USING NULL::extensions.vector(512);

UPDATE public.sv_profiles
SET
  style_version = NULL,
  style_word_count = NULL,
  style_metrics = NULL,
  updated_at = now();

CREATE INDEX IF NOT EXISTS sv_profiles_author_style_hnsw_idx
  ON public.sv_profiles
  USING hnsw (author_style_embedding extensions.vector_cosine_ops)
  WHERE author_style_embedding IS NOT NULL;

COMMENT ON COLUMN public.sv_profiles.author_style_embedding IS
  'Experimental 512D Russian stylometric fingerprint: 80 interpretable statistics + 432 hashed character n-gram features. Not a personality or cognition measurement.';

COMMENT ON COLUMN public.sv_profiles.style_version IS
  'Stylometry schema version used to compute author_style_embedding. Old profiles must be re-analysed when this value changes.';
